function bindAffiliationPicker(control,onChange=()=>{}){if(!control?.querySelector)return;const hidden=control.querySelector('input[type=hidden]'),select=control.querySelector('select'),manual=control.querySelector('.affiliation-new'),input=manual.querySelector('input');let values=affiliationValues({affiliations:hidden.value}),extra=[];function redraw(){hidden.value=JSON.stringify(values);control.querySelector('.affiliation-chips').innerHTML=values.map(v=>'<button type="button" class="keep-label affiliation-chip" data-affiliation-remove="'+esc(v)+'" aria-label="'+esc(v)+' 소속 제거"><span>'+esc(v)+'</span>'+packIcon('close')+'</button>').join('');select.innerHTML='<option value="">소속 선택</option>'+[...new Set([...affiliationCatalog(),...extra])].filter(v=>!values.includes(v)).map(v=>'<option value="'+esc(v)+'">'+esc(v)+'</option>').join('')+'<option value="__new__">새 소속 입력</option>';onChange(values)}function add(value){value=String(value||'').trim();if(!value)return;if(!values.includes(value)){values.push(value);extra.push(value);redraw()}input.value='';manual.hidden=true;select.hidden=false;select.value='';select.focus()}select.onchange=e=>{e.stopPropagation();if(select.value==='__new__'){select.hidden=true;manual.hidden=false;input.focus()}else add(select.value)};control.onclick=e=>{const remove=e.target.closest('[data-affiliation-remove]');if(remove){values=values.filter(v=>v!==remove.dataset.affiliationRemove);redraw()}else if(e.target.closest('[data-affiliation-add]'))add(input.value);else if(e.target.closest('[data-affiliation-cancel]')){manual.hidden=true;select.hidden=false;select.value='';select.focus()}};input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();add(input.value)}else if(e.key==='Escape'){e.preventDefault();manual.hidden=true;select.hidden=false;select.value='';select.focus()}};}
