function bulkMemberPatch(member,field,value,mode='replace'){const next={...member};if(field==='affiliations'){const old=affiliationValues(member),incoming=affiliationValues({affiliations:value});next.affiliations=mode==='add'?[...new Set([...old,...incoming])]:mode==='remove'?old.filter(v=>!incoming.includes(v)):incoming;next.affiliation=next.affiliations.join(' · ')}else if(['kind','nameSuffix','contact','email'].includes(field)){if(field==='kind'&&!['personal','team'].includes(value))throw Error('구분을 확인하세요');next[field]=mode==='clear'&&field!=='kind'?'':String(value).trim()}else throw Error('속성을 확인하세요');return next;}
